import 'package:pulumi/pulumi.dart';
import 'allowed_client_response.dart';
import 'nfs_share_args.dart';

/// Create an NFS share.
class NfsShare extends CustomResource {
  /// List of allowed access points.
  late final Output<List<AllowedClientResponse>> allowedClients;

  /// Labels as key value pairs.
  late final Output<Map<String, String>> labels;
  late final Output<String> location;

  /// Immutable. The name of the NFS share.
  late final Output<String> name;

  /// An identifier for the NFS share, generated by the backend. This field will be deprecated in the future, use `id` instead.
  late final Output<String> nfsShareId;

  /// Immutable. Pod name. Pod is an independent part of infrastructure. NFSShare can only be connected to the assets (networks, instances) allocated in the same pod.
  late final Output<String> pod;
  late final Output<String> project;

  /// The requested size, in GiB.
  late final Output<String> requestedSizeGib;

  /// The state of the NFS share.
  late final Output<String> state;

  /// Immutable. The storage type of the underlying volume.
  late final Output<String> storageType;

  /// The underlying volume of the share. Created automatically during provisioning.
  late final Output<String> volume;

  NfsShare(
    String name, {
    NfsShareArgs? args,
    CustomResourceOptions? options,
  }) : super(
          'google-native:baremetalsolution/v2:NfsShare',
          name,
          Input.mapToInputs(args?.toMap() ?? const {}),
          options ?? CustomResourceOptions(),
        ) {
    this.allowedClients = Output.createUnknown<List<AllowedClientResponse>>();
    this.labels = Output.createUnknown<Map<String, String>>();
    this.location = Output.createUnknown<String>();
    this.name = Output.createUnknown<String>();
    this.nfsShareId = Output.createUnknown<String>();
    this.pod = Output.createUnknown<String>();
    this.project = Output.createUnknown<String>();
    this.requestedSizeGib = Output.createUnknown<String>();
    this.state = Output.createUnknown<String>();
    this.storageType = Output.createUnknown<String>();
    this.volume = Output.createUnknown<String>();
  }
}
